-- Reference extracted verbatim from kafka_streams_recovery.log.
-- Production topic names and replicas: the test runner isolates and adapts these.
CREATE OR REPLACE STREAM ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM (IDPASSAGE STRING, MESSAGE STRUCT<NUMERO INTEGER, TYPE STRING, DHM STRING, TYPEEMISSION STRING, PRODUCTEUR STRUCT<TYPE STRING, ID STRING>>, PASSAGESORTIE STRUCT<SYSTEME STRING, DHM STRING, STATUT STRING, LOCALISATION STRUCT<GARE STRING, EQUIPEMENT STRUCT<NUMERO STRING, TYPE STRING>>, TARIFICATION STRUCT<TRAJET STRUCT<TYPE STRING, ENTREE STRUCT<ACQUISITION STRING, GARE STRING>, SORTIE STRUCT<GARE STRING, VOIE STRING, DHM STRING>>, CLASSETARIFAIRE STRUCT<CLASSE STRING, ACQUISITION STRING>, PRIX STRUCT<MONTANTHT DOUBLE, MONTANTTVA DOUBLE, MONTANTTTC DOUBLE, TAUXTVA DOUBLE>>, PAIEMENT STRUCT<RETENUS ARRAY<STRUCT<TYPE STRING, MONTANT DOUBLE, DEVISE STRING, PAN STRING>>>>) WITH (CLEANUP_POLICY='delete', KAFKA_TOPIC='asf.peage.voie.passagesortieva', KEY_FORMAT='KAFKA', VALUE_FORMAT='JSON');

CREATE OR REPLACE STREAM ASF_PEAGE_LEXVA_PASSAGESORTIEVA_LEXHISTORIC_STREAM WITH (CLEANUP_POLICY='delete', KAFKA_TOPIC='va.peage.voie.passagesortieva.lexhistoric', PARTITIONS=2, REPLICAS=4, RETENTION_MS=86400000, VALUE_FORMAT='json') AS SELECT
  ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.IDPASSAGE IDTRAN,
  ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->DHM DATETRANSACTION,
  ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->PAIEMENT->RETENUS[1]->PAN CONTENUISO,
  (CASE WHEN (LCASE(ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->PAIEMENT->RETENUS[1]->TYPE) = 'telepeagelibert') THEN 256 WHEN (LCASE(ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->PAIEMENT->RETENUS[1]->TYPE) = 'telepeagecardme') THEN 512 WHEN (LCASE(ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->PAIEMENT->RETENUS[1]->TYPE) = 'carteaccreditive') THEN 1024 WHEN (LCASE(ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->PAIEMENT->RETENUS[1]->TYPE) = 'cartemagnetique') THEN 2048 ELSE 0 END) MODEREGLEMENT,
  SUBSTRING(ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->LOCALISATION->GARE, 1, 5) SCA
FROM ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM
WHERE (LCASE(ASF_PEAGE_VOIE_PASSAGESORTIEVA_STREAM.PASSAGESORTIE->PAIEMENT->RETENUS[1]->TYPE) IN ('telepeagelibert', 'telepeagecardme', 'carteaccreditive', 'cartemagnetique'))
EMIT CHANGES;

